// AdminStudentsFees.jsx (summary)
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast from "react-hot-toast";

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [newStudent, setNewStudent] = useState({ admissionNo: "", name: "", classApplied: "" });

  useEffect(() => {
    axios.get("/api/admin/students") // you can create this route to list students
      .then(res => setStudents(res.data.data || []))
      .catch(err => console.error(err));
  }, []);

  const saveStudent = async () => {
    try {
      const res = await axios.post("/api/fees/student", newStudent);
      if (res.data.success) {
        toast.success("Student saved");
        setStudents(prev => [res.data.data, ...prev]);
      }
    } catch (err) { toast.error("Save failed") }
  };

